$ErrorActionPreference='Stop'; Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path -Parent $PSScriptRoot; $ppt=(Get-ChildItem -LiteralPath (Join-Path $root 'Bilbioteca\3. Talleres PIS') -Filter 'EDITABLE*.pptx' | Select-Object -First 1).FullName; $out=Join-Path $root 'data\faq_pis.json'
$meta=@{'0.1'=@('0. Introducción','0.1 Introducción al Plan de Integración Social');'0.2'=@('0. Introducción','0.2 Actividades del PIS');'1.1'=@('1. Visita a la obra','1.1 Proceso constructivo de la obra');'1.2'=@('1. Visita a la obra','1.2 Aspectos generales de entrega de viviendas');'1.3'=@('1. Visita a la obra','1.3 Pasos el día de la entrega');'2.1'=@('2. Uso, cuidado y mantención','2.1 Garantías y modificaciones de las viviendas');'2.2'=@('2. Uso, cuidado y mantención','2.2 Sello verde');'2.3'=@('2. Uso, cuidado y mantención','2.3 Gas de las viviendas');'3.1'=@('3. Derechos y deberes','3.1 Patrimonio reservado de la mujer casada');'3.2'=@('3. Derechos y deberes','3.2 Administración del condominio');'3.3'=@('3. Derechos y deberes','3.3 Asambleas de copropietarios/as');'3.4'=@('3. Derechos y deberes','3.4 Comité de Administración');'3.5'=@('3. Derechos y deberes','3.5 Reglamento de copropiedad');'3.6'=@('3. Derechos y deberes','3.6 Gastos comunes');'4.1'=@('4. Organización comunitaria','4.1 Organizaciones comunitarias');'4.2'=@('4. Organización comunitaria','4.2 Seguridad comunitaria')}
function Fallback($n){if($n -eq 5){'0.1'}elseif($n -le 10){'0.2'}elseif($n -eq 12){'1.1'}elseif($n -eq 13){'1.2'}elseif($n -le 15){'1.3'}elseif($n -le 22){'2.1'}elseif($n -le 24){'2.3'}elseif($n -le 28){'3.1'}elseif($n -le 31){'3.2'}elseif($n -le 33){'3.3'}elseif($n -le 36){'3.4'}elseif($n -le 39){'3.6'}elseif($n -le 45){'4.1'}else{'4.2'}}
function Header($t){foreach($k in $meta.Keys){if($t -match ('^'+[regex]::Escape($k)+'\.?\s') -and $t -notmatch '¿'){return $k}};return $null}
$zip=[IO.Compression.ZipFile]::OpenRead($ppt);$items=@();$cur=$null;$key=$null
function Save {if(!$script:cur){return};$p=@();foreach($x in $script:cur.p){$x=$x.Trim();if($x){if($p.Count -and $p[-1] -match '-$'){$p[-1]=$p[-1].Substring(0,$p[-1].Length-1)+$x}else{$p+=$x}}};if($p.Count){$m=$meta[$script:cur.k];$script:items+=[pscustomobject]@{tema=$m[0];subtema=$m[1];pregunta=$script:cur.q;respuesta=($p -join "`n`n");pagina=$script:cur.n;documento='1. Manual Resolución de dudas frecuentes PIS.pdf';ruta='Bilbioteca/3. Talleres PIS/1. Manual Resolución de dudas frecuentes PIS.pdf'}};$script:cur=$null}
for($n=1;$n -le 51;$n++){$key=if($key){$key}else{Fallback $n};$e=$zip.GetEntry("ppt/slides/slide$n.xml");if(!$e){continue};$r=[IO.StreamReader]::new($e.Open());$s=$r.ReadToEnd();$r.Close();foreach($z in [regex]::Matches($s,'<a:p(?:\s[^>]*)?>(.*?)</a:p>',[Text.RegularExpressions.RegexOptions]::Singleline)){$t=(([regex]::Matches($z.Groups[1].Value,'<a:t>(.*?)</a:t>',[Text.RegularExpressions.RegexOptions]::Singleline)|%{$_.Groups[1].Value})-join '').Trim();if(!$t -or $t -match 'EQUIDAD URBANA CONSULTORA|^\d{2}$'){continue};$h=Header $t;if($h){Save;$key=$h;continue};if($t -match '^0?[1-4]\.?\s*(Visita|Uso|Derechos|Organización)|^Referencias'){if($cur){Save};continue};$q=[regex]::Match($t,'^(?:(\d\.\d)\.?|[A-Z]\.)\s*(¿.*)$');if($q.Success){Save;$k=if($q.Groups[1].Success){$q.Groups[1].Value}else{$key};$cur=[pscustomobject]@{q=$q.Groups[2].Value;p=@();n=$n;k=$k};continue};if($cur){$cur.p+=$t}}};Save;$zip.Dispose();$items|Group-Object subtema,pregunta|%{$_.Group[0]}|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $out -Encoding utf8;Write-Output 'FAQ PPT creada.'
